// Comparison uses fetched registry records only; it does not infer treatment superiority.
const comparedTrials=new Map();
function compareTrial(id){if(comparedTrials.has(id))comparedTrials.delete(id);else{if(comparedTrials.size>=3)return toast('Compare up to three trials. Remove one to add another.');const study=[...studies,...saved].find(s=>s.protocolSection.identificationModule.nctId===id);if(study)comparedTrials.set(id,study)}refreshCompareControls()}
function refreshCompareControls(){document.querySelectorAll('[data-compare-id]').forEach(b=>{const selected=comparedTrials.has(b.dataset.compareId);b.textContent=selected?'Remove comparison':'Compare';b.setAttribute('aria-pressed',String(selected))});let bar=$('compareBar');if(!bar){bar=document.createElement('div');bar.id='compareBar';bar.className='compare-bar';$('explorer').before(bar)}bar.hidden=!comparedTrials.size;bar.innerHTML=`<span role="status">${comparedTrials.size} of 3 trials selected · selections may span searches</span><div><button class="primary" id="openComparison" ${comparedTrials.size<2?'disabled':''}>Compare selected trials</button><button class="outline" id="clearComparison">Clear</button></div>`;$('openComparison').onclick=showTrialComparison;$('clearComparison').onclick=()=>{comparedTrials.clear();refreshCompareControls()}}
function showTrialComparison(){const list=[...comparedTrials.values()];if(list.length<2)return;const reported=v=>esc(v||'Not reported');const rows=[['Registry status',s=>reported(s.protocolSection.statusModule?.overallStatus?.replaceAll('_',' '))],['Phase',s=>reported(s.protocolSection.designModule?.phases?.join(' / ').replaceAll('PHASE','Phase '))],['Therapies',s=>reported(s.protocolSection.armsInterventionsModule?.interventions?.map(i=>i.name+' ('+i.type+')').join('; '))],['Enrollment',s=>{const v=s.protocolSection.designModule?.enrollmentInfo;return v?esc(v.count)+' · '+reported(v.type):'Not reported'}],['Design',s=>{const d=s.protocolSection.designModule||{};return reported([d.studyType,d.designInfo?.allocation,d.designInfo?.interventionModel,d.designInfo?.maskingInfo?.masking].filter(Boolean).join(' · '))}],['Planned primary endpoints',s=>(s.protocolSection.outcomesModule?.primaryOutcomes||[]).map(o=>'<p>'+esc(o.measure)+(o.timeFrame?' · '+esc(o.timeFrame):'')+'</p>').join('')||'Not reported'],['Posted registry results',s=>s.resultsSection?'Results section available · open full trial for reported analyses and confidence limits':'No results section returned'],['Eligibility',s=>{const e=s.protocolSection.eligibilityModule||{};return reported([e.minimumAge,e.maximumAge,e.sex].filter(Boolean).join(' · '))+'<details><summary>Read full criteria</summary><p class="preserve-lines">'+reported(e.eligibilityCriteria)+'</p></details>'}],['Record updated',s=>reported(s.protocolSection.statusModule?.lastUpdatePostDateStruct?.date)]];
showDialog(`<h2>Compare trial designs</h2><p>These records were fetched during your browsing session. Status may change. Differences in populations, endpoints, and follow-up prevent a simple ranking of treatments. Enrollment may be estimated or actual, as labeled.</p><div class="compare-table-wrap"><table class="compare-table"><caption>Side-by-side ClinicalTrials.gov records</caption><thead><tr><th scope="col">Field</th>${list.map(s=>`<th scope="col">${esc(s.protocolSection.identificationModule.nctId)}<p>${esc(s.protocolSection.identificationModule.briefTitle)}</p><button class="outline" data-open-compared="${esc(s.protocolSection.identificationModule.nctId)}">Full trial details</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,read])=>`<tr><th scope="row">${label}</th>${list.map(s=>'<td>'+read(s)+'</td>').join('')}</tr>`).join('')}</tbody></table></div>`);$('dialog').classList.add('trial-detail');document.querySelectorAll('[data-open-compared]').forEach(b=>b.onclick=()=>details(b.dataset.openCompared))}
const renderWithoutComparison=renderTrials;
renderTrials=function(){renderWithoutComparison();document.querySelectorAll('#trials .trial').forEach(card=>{const id=card.querySelector('.save')?.getAttribute('aria-label')?.match(/NCT\d{8}/)?.[0];if(!id)return;const b=document.createElement('button');b.className='outline compare-toggle';b.dataset.compareId=id;b.onclick=()=>compareTrial(id);card.querySelector('.trialtop').append(b)});refreshCompareControls()};
